        importStockHintset: "\u0909\u0926\u093e\u0939\u0930\u0923: \u092a\u0941\u0930\u093e\u0928\u0947 10 \u0915\u0940 \u091c\u0917\u0939 \u092b\u093c\u093e\u0907\u0932 \u0915\u0947 5 \u0939\u094b \u091c\u093e\u090f\u0901\u0917\u0947\u0964 \u0924\u093e\u091c\u093c\u093e \u0917\u093f\u0928\u0924\u0940 \u0915\u0947 \u0932\u093f\u090f \u091a\u0941\u0928\u0947\u0902\u0964 \u0916\u093e\u0932\u0940 \u0938\u094d\u091f\u0949\u0915 \u0938\u0947\u0932 \u0938\u0947 \u0938\u094d\u091f\u0949\u0915 \u0928\u0939\u0940\u0902 \u092c\u0926\u0932\u0947\u0917\u093e\u0964",
        importMatchHelp: "\u092f\u0947 \u0928\u093e\u092e \u092a\u0939\u0932\u0947 \u0938\u0947 \u0939\u0948\u0902, \u0932\u0947\u0915\u093f\u0928 \u092b\u093c\u093e\u0907\u0932 \u092e\u0947\u0902 \u092c\u093e\u0930\u0915\u094b\u0921 \u092f\u093e SKU \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0935\u0939\u0940 \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0939\u094b \u0924\u092d\u0940 \u092a\u0941\u0930\u093e\u0928\u0947 \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0915\u094b \u091a\u0941\u0928\u0947\u0902\u0964",
        importMatchChoose: "\u092e\u093f\u0932\u0924\u093e \u0939\u0941\u0906 \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u091a\u0941\u0928\u0947\u0902",
        importMatchNew: "\u092f\u0939 \u0905\u0932\u0917, \u0928\u092f\u093e \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0939\u0948",
