        importPriceUpdate: "\u0907\u0938 \u092b\u093c\u093e\u0907\u0932 \u0915\u0947 \u0926\u093e\u092e \u0932\u0917\u093e\u090f\u0901",
        importPriceHint: "\u092c\u093f\u0915\u094d\u0930\u0940, \u0916\u0930\u0940\u0926, MRP \u0914\u0930 \u0916\u0941\u0932\u0947 \u092e\u093e\u0932 \u0915\u0947 \u0926\u093e\u092e \u0907\u0938 \u0935\u093f\u0915\u0932\u094d\u092a \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u092c\u0926\u0932\u0947\u0902\u0917\u0947\u0964 \u0916\u093e\u0932\u0940 \u0938\u0947\u0932 \u092e\u0947\u0902 \u092a\u0941\u0930\u093e\u0928\u093e \u0926\u093e\u092e \u0930\u0939\u0947\u0917\u093e\u0964 \u0928\u090f \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0915\u093e \u092c\u093f\u0915\u094d\u0930\u0940 \u0926\u093e\u092e \u091c\u093c\u0930\u0942\u0930\u0940 \u0939\u0948\u0964",
