        importBelowCost: "{count} \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0915\u093e \u092c\u093f\u0915\u094d\u0930\u0940 \u0926\u093e\u092e \u0916\u0930\u0940\u0926 \u0926\u093e\u092e \u0938\u0947 \u0915\u092e \u0939\u094b\u0917\u093e\u0964 \u0906\u0917\u0947 \u092c\u0922\u093c\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u091c\u093e\u0901\u091a\u0947\u0902\u0964",
        importAboveMrp: "{count} \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0915\u093e \u092c\u093f\u0915\u094d\u0930\u0940 \u0926\u093e\u092e MRP \u0938\u0947 \u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0939\u0948\u0964 \u0906\u0917\u0947 \u092c\u0922\u093c\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092b\u093c\u093e\u0907\u0932 \u0920\u0940\u0915 \u0915\u0930\u0947\u0902\u0964",
        importPriceFieldprice: "\u092c\u093f\u0915\u094d\u0930\u0940 \u0926\u093e\u092e",
