        importPreviewWait: "\u092b\u093c\u093e\u0907\u0932 \u0915\u094b {time} (\u092e\u093f\u0928\u091f:\u0938\u0947\u0915\u0902\u0921) \u092c\u093e\u0926 \u092b\u093f\u0930 \u091c\u093e\u0901\u091a \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964",
        importWriteWait: "{time} (\u092e\u093f\u0928\u091f:\u0938\u0947\u0915\u0902\u0921) \u092c\u093e\u0926 \u092b\u093f\u0930 \u0907\u092e\u094d\u092a\u094b\u0930\u094d\u091f \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964",
