        importPaused: "\u0906\u0917\u0947 \u092c\u0922\u093c\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0925\u094b\u0921\u093c\u093e \u0930\u0941\u0915\u0947\u0902",
        importWaitReady: "\u0905\u092c \u0906\u0917\u0947 \u092c\u0922\u093c \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u092b\u093c\u093e\u0907\u0932 \u091c\u093e\u0901\u091a\u0947\u0902, \u092b\u093f\u0930 \u0907\u092e\u094d\u092a\u094b\u0930\u094d\u091f \u0915\u0930\u0947\u0902\u0964",
