        importReviewNew: "\u092b\u093c\u093e\u0907\u0932 \u092e\u0947\u0902 \u0928\u090f \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f",
        importReviewExisting: "\u092a\u0939\u0932\u0947 \u0938\u0947 \u0938\u0947\u0935 \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f",
        importReviewPriceCount: "{count} \u092a\u0941\u0930\u093e\u0928\u0947 \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0915\u0940 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0917\u0940\u0964",
        importReviewStockCount: "{count} \u092a\u0941\u0930\u093e\u0928\u0947 \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u0915\u093e \u0938\u094d\u091f\u0949\u0915 \u0907\u0938 \u092b\u093c\u093e\u0907\u0932 \u092e\u0947\u0902 \u0905\u0932\u0917 \u0939\u0948\u0964",
        importReviewStockWarn: "स्टॉक वही हो जाएगा जो शीट में लिखा है। अगर यह शीट अभी की गिनती से नहीं बनी, तो आज की बिक्री का हिसाब मिट जाएगा।",
        importReviewNoChange: "\u0907\u0928 \u0935\u093f\u0915\u0932\u094d\u092a\u094b\u0902 \u0938\u0947 \u092a\u0941\u0930\u093e\u0928\u0947 \u092a\u094d\u0930\u094b\u0921\u0915\u094d\u091f \u092e\u0947\u0902 \u0915\u094b\u0908 \u092c\u0926\u0932\u093e\u0935 \u0928\u0939\u0940\u0902 \u0939\u094b\u0917\u093e\u0964",
